-- BERISI HASH KATA SANDI (bcrypt) AKUN ASLI. Perlakukan sebagai RAHASIA; jangan dibagikan atau di-commit.
-- Jalankan SETELAH 01, 02, 03. Opsional: bila server baru memakai akun ADMIN dari scripts/awal_unit_admin.sql, file ini boleh dilewati.
-- Aman diulang untuk akun (dilewati bila user_id atau username sudah ada).
-- Catatan: foto profil dan kode HRMB mandor di akun ikut sebagaimana adanya (kode HRMB mungkin masih kosong/sementara).
-- Jalankan dengan: sqlcmd -S <server> -d <database> -U <akun> -I -b -f 65001 -i <berkas>

SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
GO
